/**
 * Reading the BigCommerce Storefront API token off the page.
 *
 * Themes are expected to publish it as `window.graphQLToken` or
 * `window.storeConfig.storefrontToken`, but many never do — leaving the SDK with
 * no token and every hydration call failing, which shows up as product cards
 * with no image.
 *
 * BigCommerce itself always renders the token into the Stencil jsContext: the
 * JSON blob passed as the second argument to
 * `window.stencilBootstrap(template, context)`. That is a platform convention
 * rather than a per-theme one, so it is the right fallback when a theme exposes
 * neither global. The token is rendered for every visitor, not just an
 * authenticated admin session.
 *
 * It is deliberately read from the DOM on each call rather than captured once:
 * BigCommerce re-mints the token per page render with a short expiry, so it can
 * be neither hardcoded in a theme nor stored server-side without going stale.
 */

const BOOTSTRAP_MARKER = 'stencilBootstrap';

// jsContext reaches the DOM as a JSON *string literal* argument, so its quotes
// arrive backslash-escaped. Themes that inline the object unescaped also exist,
// so accept both rather than betting on one.
const TOKEN_PATTERNS: readonly RegExp[] = [
  /\\"token\\":\\"([\w.-]+)\\"/,
  /"token":"([\w.-]+)"/,
];

// Three dot-separated segments — the shape BigCommerce issues. Guards against
// lifting some unrelated `token` field out of a script that happens to mention
// the bootstrap call.
const JWT_SHAPE = /^[\w-]+\.[\w-]+\.[\w-]+$/;

let cachedToken: string | null = null;

/**
 * The Storefront API token from the Stencil jsContext, or `null` when the page
 * has no such context (SSR, a non-Stencil page, or a theme that renders it
 * differently). Never throws — a missing token is a normal outcome the caller
 * already handles.
 */
export function readStencilContextToken(doc?: Document): string | null {
  if (cachedToken) return cachedToken;

  const target = doc ?? (typeof document !== 'undefined' ? document : null);
  if (!target) return null;

  for (const script of Array.from(target.querySelectorAll('script:not([src])'))) {
    const text = script.textContent;
    if (!text || !text.includes(BOOTSTRAP_MARKER)) continue;

    for (const pattern of TOKEN_PATTERNS) {
      const token = text.match(pattern)?.[1];
      // Only a hit is cached. A miss can simply mean the SDK ran before the
      // inline bootstrap script parsed, and the next call should look again.
      if (token && JWT_SHAPE.test(token)) {
        cachedToken = token;
        return token;
      }
    }
  }

  return null;
}

/** Clears the memoised token. Exists for tests, which reuse one JSDOM window. */
export function resetStencilContextTokenCache(): void {
  cachedToken = null;
}
