/**
 * SearchTypeaheadSections — presentational render of the four federated
 * typeahead sections (products → categories → content → brands), per
 * verdict-SOI-708-fast-search-path/docs/typeahead-frontend-spec.md.
 *
 * Pure / stateless: it renders whatever sections it's handed and reports
 * activation back via `onSelect`. The owner manages query state (useTypeaheadSearch)
 * and keyboard focus (activeId + the flattenHits helper below). Backend owns
 * ranking, filtering and ordering — this component never re-sorts.
 *
 * ARIA: implements the combobox/listbox pattern. Each non-empty section is a
 * role="group" with a header; hits are role="option" with stable ids so the
 * input's aria-activedescendant can point at the focused row.
 */

import React from 'react';
import {
  TYPEAHEAD_SECTION_ORDER,
  type TypeaheadSections,
  type TypeaheadSectionKey,
  type TypeaheadAnyHit,
  type ProductHit,
  type CategoryHit,
  type ContentHit,
  type BrandHit,
  type TypeaheadHighlight,
} from '@swiftotter/omniguide-core';
import { isValidNavigationUrl } from '../../utils/navigation.js';

const SECTION_LABELS: Record<TypeaheadSectionKey, string> = {
  products: 'Products',
  categories: 'Categories',
  content: 'Guides & Help',
  brands: 'Brands',
};

const CONTENT_SNIPPET_MAX = 140;

export interface FlatHit {
  sectionKey: TypeaheadSectionKey;
  hit: TypeaheadAnyHit;
  /** Stable option id; matches the rendered element id + aria-activedescendant. */
  optionId: string;
  /** Index within the flattened list (for arrow-key navigation). */
  index: number;
}

/**
 * Flatten the sections into a single ordered list for linear keyboard
 * navigation across section boundaries. Order mirrors the rendered order
 * (TYPEAHEAD_SECTION_ORDER); empty sections contribute nothing.
 */
export function flattenHits(
  sections: TypeaheadSections,
  idPrefix: string,
): FlatHit[] {
  const flat: FlatHit[] = [];
  let index = 0;
  for (const sectionKey of TYPEAHEAD_SECTION_ORDER) {
    const hits = sections[sectionKey].hits as TypeaheadAnyHit[];
    hits.forEach((hit, i) => {
      flat.push({
        sectionKey,
        hit,
        optionId: `${idPrefix}-${sectionKey}-${i}`,
        index: index++,
      });
    });
  }
  return flat;
}

/** Pick the highlight snippet for a given field, falling back to the raw value. */
/** Tokens that matched a given field — drives where we draw <mark> highlights. */
function matchedTokensFor(
  highlights: TypeaheadHighlight[] | undefined,
  field: string,
): string[] {
  return highlights?.find((h) => h.field === field)?.matched_tokens ?? [];
}

function escapeRegExp(s: string): string {
  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/**
 * Render `value` with the matched tokens wrapped in <mark>, built from React
 * text nodes — never `dangerouslySetInnerHTML`. The backend also returns a
 * pre-rendered `snippet` HTML string, but injecting it would trust the backend
 * to have sanitized catalog/UGC-derived content; instead we drive the highlight
 * from `matched_tokens` (presentation only, no scoring) so React escapes the
 * text and no server markup can reach the DOM. XSS surface eliminated.
 */
const HighlightedText: React.FC<{
  highlights: TypeaheadHighlight[] | undefined;
  field: string;
  value: string;
  className?: string;
}> = ({ highlights, field, value, className }) => {
  const tokens = matchedTokensFor(highlights, field).filter(
    (t) => typeof t === 'string' && t.trim().length > 0,
  );
  if (tokens.length === 0) {
    return <span className={className}>{value}</span>;
  }
  // One capturing group → split() interleaves [text, match, text, match, …];
  // odd indices are the matched substrings (original casing preserved).
  const pattern = new RegExp(`(${tokens.map(escapeRegExp).join('|')})`, 'ig');
  const parts = value.split(pattern);
  return (
    <span className={className}>
      {parts.map((part, i) =>
        i % 2 === 1 ? (
          // eslint-disable-next-line react/no-array-index-key -- positional split of one string; no stable id and order is fixed
          <mark key={i}>{part}</mark>
        ) : (
          // eslint-disable-next-line react/no-array-index-key -- positional split of one string; no stable id and order is fixed
          <React.Fragment key={i}>{part}</React.Fragment>
        ),
      )}
    </span>
  );
};

function truncate(text: string, max: number): string {
  if (text.length <= max) return text;
  return `${text.slice(0, max).trimEnd()}…`;
}

export interface SearchTypeaheadSectionsProps {
  sections: TypeaheadSections;
  /** id prefix shared with flattenHits so option ids line up. */
  idPrefix: string;
  /** Currently keyboard-focused option id, or null. */
  activeId: string | null;
  /** Fired on click/Enter for a hit — owner navigates to hit.url. */
  onSelect: (hit: TypeaheadAnyHit, sectionKey: TypeaheadSectionKey) => void;
  /**
   * Resolves a hit to the absolute URL it points at, or undefined if it has
   * none. Supplied by the owner because resolving a relative hit URL needs the
   * configured store base, which this presentational component does not have.
   */
  hrefFor?: (hit: TypeaheadAnyHit) => string | undefined;
  /** Fired on hover so the owner can sync the active index to the pointer. */
  onHover?: (optionId: string) => void;
}

export const SearchTypeaheadSections: React.FC<SearchTypeaheadSectionsProps> = ({
  sections,
  idPrefix,
  activeId,
  onSelect,
  onHover,
  hrefFor,
}) => {
  return (
    <div className="omniguide-ta" role="listbox" id={`${idPrefix}-listbox`}>
      {TYPEAHEAD_SECTION_ORDER.map((sectionKey) => {
        const hits = sections[sectionKey].hits;
        if (hits.length === 0) return null;
        return (
          <div
            key={sectionKey}
            className="omniguide-ta__section"
            role="group"
            aria-label={SECTION_LABELS[sectionKey]}
          >
            <div className="omniguide-ta__section-head" aria-hidden="true">
              {SECTION_LABELS[sectionKey]}
            </div>
            <ul className="omniguide-ta__list">
              {hits.map((hit, i) => {
                const optionId = `${idPrefix}-${sectionKey}-${i}`;
                const active = optionId === activeId;
                return (
                  <li
                    key={hit.id || optionId}
                    id={optionId}
                    role="option"
                    aria-selected={active}
                    className={`omniguide-ta__row omniguide-ta__row--${sectionKey}${
                      active ? ' omniguide-ta__row--active' : ''
                    }`}
                    onMouseEnter={() => onHover?.(optionId)}
                  >
                    {/* A real anchor, so a row behaves like the link it is:
                        Cmd/Ctrl-click and middle-click open a new tab, Shift a
                        new window, right-click offers "Open in new tab" and
                        "Copy link address", and the target shows in the status
                        bar on hover. All six are the browser's, for free — a
                        modifier-key branch in a click handler buys one.

                        `display: contents` in CSS, so it adds no box and the
                        row's flex layout is untouched. ARIA makes the
                        descendants of a `role="option"` presentational, so the
                        link role is suppressed either way and a screen reader
                        still hears one option, not an option wrapping a link.
                        It stays out of the tab order for the same reason: the
                        listbox is driven by aria-activedescendant. */}
                    <a
                      className="omniguide-ta__row-link"
                      href={hrefFor?.(hit)}
                      tabIndex={-1}
                      draggable={false}
                      // Button 0 only. Keeping focus in the search field is
                      // what this is for, and preventing the default on a
                      // middle-click would take its new-tab with it.
                      onMouseDown={(e) => {
                        if (e.button === 0) e.preventDefault();
                      }}
                      onClick={(e) => {
                        // A modified click is the browser's to handle — let it
                        // through untouched rather than navigating this tab.
                        if (e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return;
                        // A plain click takes the owner's path instead of the
                        // href, because that is what carries the tracking.
                        e.preventDefault();
                        onSelect(hit, sectionKey);
                      }}
                    >
                      {renderRow(sectionKey, hit)}
                    </a>
                  </li>
                );
              })}
            </ul>
          </div>
        );
      })}
    </div>
  );
};

function renderRow(sectionKey: TypeaheadSectionKey, hit: TypeaheadAnyHit): React.ReactNode {
  switch (sectionKey) {
    case 'products':
      return <ProductRow hit={hit as ProductHit} />;
    case 'categories':
      return <CategoryRow hit={hit as CategoryHit} />;
    case 'content':
      return <ContentRow hit={hit as ContentHit} />;
    case 'brands':
      return <BrandRow hit={hit as BrandHit} />;
    default:
      return null;
  }
}

const ProductRow: React.FC<{ hit: ProductHit }> = ({ hit }) => (
  <>
    <span className="omniguide-ta__thumb" aria-hidden="true">
      {hit.image_url && isValidNavigationUrl(hit.image_url) ? (
        <img src={hit.image_url} alt="" loading="lazy" />
      ) : (
        <span className="omniguide-ta__thumb-fallback" />
      )}
    </span>
    <span className="omniguide-ta__body">
      <HighlightedText
        className="omniguide-ta__title"
        highlights={hit.highlights}
        field="title"
        value={hit.title}
      />
      <span className="omniguide-ta__meta">
        {hit.brand && <span className="omniguide-ta__brand">{hit.brand}</span>}
        {hit.brand && hit.sku && <span aria-hidden="true"> · </span>}
        {hit.sku && <span className="omniguide-ta__sku">SKU: {hit.sku}</span>}
      </span>
    </span>
    {typeof hit.price === 'number' && (
      <span className="omniguide-ta__price">${hit.price.toFixed(2)}</span>
    )}
  </>
);

const CategoryRow: React.FC<{ hit: CategoryHit }> = ({ hit }) => (
  <>
    <span className="omniguide-ta__icon" aria-hidden="true">
      <FolderGlyph />
    </span>
    <span className="omniguide-ta__body">
      <HighlightedText
        className="omniguide-ta__title"
        highlights={hit.highlights}
        field="name"
        value={hit.name}
      />
    </span>
    <span className="omniguide-ta__count">
      {hit.product_count ?? ''}
      {hit.product_count != null && <span className="sr-only"> products</span>}
    </span>
  </>
);

const ContentRow: React.FC<{ hit: ContentHit }> = ({ hit }) => (
  <>
    <span className="omniguide-ta__icon" aria-hidden="true">
      <DocGlyph />
    </span>
    <span className="omniguide-ta__body">
      <HighlightedText
        className="omniguide-ta__title"
        highlights={hit.highlights}
        field="title"
        value={hit.title}
      />
      {hit.snippet && (
        <span className="omniguide-ta__snippet">
          {truncate(hit.snippet, CONTENT_SNIPPET_MAX)}
        </span>
      )}
    </span>
  </>
);

const BrandRow: React.FC<{ hit: BrandHit }> = ({ hit }) => (
  <>
    <span className="omniguide-ta__icon" aria-hidden="true">
      <TagGlyph />
    </span>
    <span className="omniguide-ta__body">
      <HighlightedText
        className="omniguide-ta__title"
        highlights={hit.highlights}
        field="name"
        value={hit.name}
      />
    </span>
    <span className="omniguide-ta__count">
      {hit.product_count ?? ''}
      {hit.product_count != null && <span className="sr-only"> products</span>}
    </span>
  </>
);

/* — small inline glyphs (no external icon deps) — */
const FolderGlyph: React.FC = () => (
  <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden="true">
    <path
      d="M1.5 4a1 1 0 0 1 1-1h3.2l1.2 1.4H13a1 1 0 0 1 1 1V12a1 1 0 0 1-1 1H2.5a1 1 0 0 1-1-1V4Z"
      stroke="currentColor"
      strokeWidth="1.2"
    />
  </svg>
);
const DocGlyph: React.FC = () => (
  <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden="true">
    <path d="M4 2h5l3 3v9H4V2Z" stroke="currentColor" strokeWidth="1.2" />
    <path d="M9 2v3h3M6 8h4M6 10.5h4" stroke="currentColor" strokeWidth="1.2" />
  </svg>
);
const TagGlyph: React.FC = () => (
  <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden="true">
    <path
      d="M2.5 2.5h5l6 6-5 5-6-6v-5Z"
      stroke="currentColor"
      strokeWidth="1.2"
    />
    <circle cx="5" cy="5" r="1" fill="currentColor" />
  </svg>
);
