import React, { useState } from 'react';
import { DiscoveryAutocomplete } from '../discovery/DiscoveryAutocomplete.js';
import type { AnswerChoice, AutocompleteRenderHint } from '../discovery/DiscoveryAutocomplete.js';

const UNSELECTED = Symbol('unselected');

/**
 * Answer ids are nullable: the backend sends the "Other" free-text option with
 * `id: null` because there is no stored answer row to reference.
 */
export type IntentAnswerId = string | number | null;

export interface IntentAnswer {
    id: IntentAnswerId;
    answer?: string;
    answer_text?: string;
    explanation?: string;
    is_other_option?: boolean;
}

export interface IntentQuestion {
    id?: string | number;
    question_id?: string | number;
    question?: string;
    question_text?: string;
    answers: IntentAnswer[];
    _isDiscoveryQuestion?: boolean;
    /** CFQ render variant (SOI-616): 'choice' | 'autocomplete' | 'searchable_dropdown'. */
    answer_render_hint?: string;
    /** Pre-sorted choices for autocomplete/searchable_dropdown questions. */
    answer_choices?: AnswerChoice[];
}

export interface SearchIntentQuestionUIProps {
    intentQuestion: IntentQuestion;
    onAnswerClick: (answerText: string, answerId: IntentAnswerId, options?: Record<string, unknown>) => void;
    onCustomAnswer: (customText: string) => void;
    /** 'search' renders the conversation discovery "guide" card (eyebrow + question). */
    variant?: 'search' | 'category';
}

export const SearchIntentQuestionUI: React.FC<SearchIntentQuestionUIProps> = ({
    intentQuestion,
    onAnswerClick,
    onCustomAnswer,
    variant = 'search',
}) => {
    const [customInput, setCustomInput] = useState('');
    const [selectedAnswerId, setSelectedAnswerId] = useState<IntentAnswerId | symbol>(UNSELECTED);
    const [showOtherInput, setShowOtherInput] = useState(false);
    const [hoveredId, setHoveredId] = useState<IntentAnswerId | symbol>(UNSELECTED);

    if (!intentQuestion) return null;

    const isDiscoveryQuestion = intentQuestion._isDiscoveryQuestion;
    const hasOtherOption = intentQuestion.answers?.some(a => a.is_other_option);
    const isGuide = variant === 'search';
    const questionText = intentQuestion.question_text || intentQuestion.question;

    // CFQ autocomplete (SOI-616): reuse the discovery wizard's choice renderer.
    const renderHint = intentQuestion.answer_render_hint ?? 'choice';
    const choices = intentQuestion.answer_choices ?? [];
    const useChoiceRenderer = renderHint !== 'choice' && choices.length > 0;

    // answer_id is null for CFQ picks — the backend resolves answer_text → AttributeValue.
    const handleSelectChoice = (choice: AnswerChoice) => {
        setSelectedAnswerId(choice.id);
        onAnswerClick(choice.value, choice.id, { isOtherAnswer: false });
    };

    const handleAnswerClick = (answer: IntentAnswer) => {
        const answerText = answer.answer_text || answer.answer || '';

        if (answer.is_other_option) {
            setSelectedAnswerId(answer.id);
            setShowOtherInput(true);
            return;
        }

        setSelectedAnswerId(answer.id);
        setShowOtherInput(false);

        if (isDiscoveryQuestion) {
            onAnswerClick(answerText, answer.id, {
                isOtherAnswer: false,
            });
        } else {
            onAnswerClick(answerText, answer.id);
        }
    };

    const handleOtherClick = () => {
        setSelectedAnswerId('other');
        setShowOtherInput(true);
    };

    const handleCustomSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (customInput.trim()) {
            if (isDiscoveryQuestion) {
                const otherAnswer = intentQuestion.answers?.find(a => a.is_other_option);
                if (otherAnswer) {
                    onAnswerClick(customInput.trim(), otherAnswer.id, {
                        isOtherAnswer: true,
                        otherAnswerText: customInput.trim(),
                    });
                } else {
                    onCustomAnswer(customInput.trim());
                }
            } else {
                onCustomAnswer(customInput.trim());
            }
            setCustomInput('');
        }
    };

    return (
        <div className={`omniguide-intent-question ${isGuide ? 'omniguide-intent-question--guide' : ''}`}>
            {isGuide && (
                <div className="omniguide-intent-question__eyebrow">
                    <span className="omniguide-intent-question__mark" aria-hidden="true" />
                    To narrow this down
                </div>
            )}
            {isGuide && questionText && (
                <p className="omniguide-intent-question__text">{questionText}</p>
            )}
            {useChoiceRenderer ? (
                <DiscoveryAutocomplete
                    questionId={String(intentQuestion.question_id ?? intentQuestion.id ?? '')}
                    choices={choices}
                    onSelectChoice={handleSelectChoice}
                    selectedValue={
                        choices.find(c => c.id === selectedAnswerId)?.value ?? null
                    }
                    ariaLabel={questionText}
                    renderHint={
                        (renderHint === 'searchable_dropdown'
                            ? 'searchable_dropdown'
                            : 'autocomplete') as AutocompleteRenderHint
                    }
                />
            ) : (
            <div className="omniguide-intent-answers">
                {intentQuestion.answers.map((answer, index) => {
                    const isSelected = selectedAnswerId === answer.id;
                    const displayText = answer.is_other_option ? 'Other' : (answer.answer_text || answer.answer);

                    return (
                        <button
                            key={answer.id ?? `answer-${index}`}
                            onClick={() => handleAnswerClick(answer)}
                            className="omniguide-intent-answer-btn"
                            data-selected={isSelected}
                            data-hovered={hoveredId === answer.id}
                            onMouseEnter={() => setHoveredId(answer.id)}
                            onMouseLeave={() => setHoveredId(UNSELECTED)}
                            title={answer.explanation || ''}
                        >
                            {displayText}
                        </button>
                    );
                })}
                {!hasOtherOption && (
                    <button
                        onClick={handleOtherClick}
                        className="omniguide-intent-answer-btn"
                        data-selected={selectedAnswerId === 'other'}
                        data-hovered={hoveredId === 'other'}
                        onMouseEnter={() => setHoveredId('other')}
                        onMouseLeave={() => setHoveredId(UNSELECTED)}
                    >
                        Other
                    </button>
                )}
            </div>
            )}
            {!useChoiceRenderer && showOtherInput && (
                <form onSubmit={handleCustomSubmit} className="omniguide-intent-custom-form">
                    <input
                        type="text"
                        value={customInput}
                        onChange={(e) => setCustomInput(e.target.value)}
                        placeholder="Type your answer..."
                        className="omniguide-intent-custom-input"
                        autoFocus
                    />
                    <button
                        type="submit"
                        disabled={!customInput.trim()}
                        className="omniguide-intent-custom-submit"
                        data-disabled={!customInput.trim()}
                    >
                        Send
                    </button>
                </form>
            )}
        </div>
    );
};
