/**
 * useTypeaheadSearch — drives the federated typeahead surface beneath the
 * search input (SOI-708).
 *
 * Implements the non-negotiable behaviors from
 * verdict-SOI-708-fast-search-path/docs/typeahead-frontend-spec.md:
 *  - 120ms debounce
 *  - Minimum 2 characters before firing
 *  - Monotonic request-id guard against out-of-order responses
 *  - AbortController cancellation of superseded requests
 *  - 503 disables the typeahead surface for the rest of the session
 *  - `is_question=true` short-circuits section rendering
 *
 * The hook owns query/sections/disabled/isQuestion/loading state. It does NOT
 * own focused-index or open/closed visibility — those are UI concerns owned
 * by the dropdown component.
 */

import { useCallback, useEffect, useRef, useState } from 'react';
import {
  fetchTypeaheadSearch,
  getCurrentPage,
  sanitizeUrl,
  type TypeaheadSections,
} from '@swiftotter/omniguide-core';
import { useOmniguideContext } from '../context/OmniguideProvider.js';

export const TYPEAHEAD_DEBOUNCE_MS = 120;
export const TYPEAHEAD_MIN_QUERY_LENGTH = 2;
/** Spec default for the products section; backend applies per-section defaults. */
export const TYPEAHEAD_DEFAULT_PER_PAGE = 8;

const EMPTY_SECTIONS: TypeaheadSections = {
  products: { found: 0, hits: [] },
  categories: { found: 0, hits: [] },
  content: { found: 0, hits: [] },
  brands: { found: 0, hits: [] },
};

/**
 * Coerce whatever the backend returned into a complete TypeaheadSections.
 * Tolerates partial/missing sections and malformed payloads so a flaky
 * response never crashes the dropdown — anything uninterpretable is empty.
 */
function normalizeSections(data: unknown): TypeaheadSections {
  if (!data || typeof data !== 'object') return EMPTY_SECTIONS;
  const sections = (data as { sections?: unknown }).sections;
  if (!sections || typeof sections !== 'object') return EMPTY_SECTIONS;
  const obj = sections as Record<string, unknown>;

  const coerce = (v: unknown) => {
    if (!v || typeof v !== 'object') return { found: 0, hits: [] };
    const sect = v as { found?: unknown; hits?: unknown };
    const hits = Array.isArray(sect.hits) ? sect.hits : [];
    const found = typeof sect.found === 'number' ? sect.found : hits.length;
    return { found, hits };
  };

  return {
    products: coerce(obj['products']) as TypeaheadSections['products'],
    categories: coerce(obj['categories']) as TypeaheadSections['categories'],
    content: coerce(obj['content']) as TypeaheadSections['content'],
    brands: coerce(obj['brands']) as TypeaheadSections['brands'],
  };
}

function isAllEmpty(s: TypeaheadSections): boolean {
  return (
    s.products.hits.length === 0 &&
    s.categories.hits.length === 0 &&
    s.content.hits.length === 0 &&
    s.brands.hits.length === 0
  );
}

export interface UseTypeaheadSearchOptions {
  /** Per-section page size override. Backend caps at 20. */
  perPage?: number;
  /** When true, includes out-of-stock products. */
  allowOos?: boolean;
}

export interface UseTypeaheadSearchReturn {
  /** Full federated sections (products/categories/content/brands). */
  sections: TypeaheadSections;
  /** Last successfully-resolved query, echoed from the backend. */
  resolvedQuery: string;
  /** True while a request is in flight (after the debounce fires). */
  isLoading: boolean;
  /** True once the backend returned 503 — hide the surface for the session. */
  isDisabled: boolean;
  /** True when the backend flagged the query a natural-language question. */
  isQuestion: boolean;
  /** True when the latest response had zero hits across all sections. */
  hasResolvedEmpty: boolean;
  /** Push a raw query into the controller. Debounced internally. */
  setQuery: (rawQuery: string) => void;
  /** Wipe results and cancel any in-flight request without disabling. */
  reset: () => void;
}

export function useTypeaheadSearch(
  options: UseTypeaheadSearchOptions = {},
): UseTypeaheadSearchReturn {
  const { config } = useOmniguideContext();
  const apiBaseUrl = config.apiBaseUrl;
  const websiteCode = config.websiteId;

  const [sections, setSections] = useState<TypeaheadSections>(EMPTY_SECTIONS);
  const [resolvedQuery, setResolvedQuery] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isDisabled, setIsDisabled] = useState(false);
  const [isQuestion, setIsQuestion] = useState(false);
  const [hasResolvedEmpty, setHasResolvedEmpty] = useState(false);

  const nextIdRef = useRef(0);
  const lastRenderedIdRef = useRef(-1);
  const debounceTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const abortRef = useRef<AbortController | null>(null);

  // Keep latest options without re-creating fire()/setQuery on every render.
  const optionsRef = useRef(options);
  optionsRef.current = options;

  const clearTimer = () => {
    if (debounceTimerRef.current !== null) {
      clearTimeout(debounceTimerRef.current);
      debounceTimerRef.current = null;
    }
  };

  const clearResults = () => {
    setSections(EMPTY_SECTIONS);
    setIsQuestion(false);
    setHasResolvedEmpty(false);
  };

  const reset = useCallback(() => {
    clearTimer();
    abortRef.current?.abort();
    abortRef.current = null;
    clearResults();
    setResolvedQuery('');
    setIsLoading(false);
  }, []);

  const fire = useCallback(
    async (query: string) => {
      if (!apiBaseUrl || !websiteCode) return;

      const myId = ++nextIdRef.current;
      abortRef.current?.abort();
      const controller = new AbortController();
      abortRef.current = controller;

      setIsLoading(true);

      const result = await fetchTypeaheadSearch({
        apiBaseUrl,
        request: {
          website_code: websiteCode,
          query,
          per_page: optionsRef.current.perPage ?? TYPEAHEAD_DEFAULT_PER_PAGE,
          allow_oos: optionsRef.current.allowOos ?? false,
        },
        // getCurrentPage(), not window.location.href: the backend resolves the
        // tenant from this header (X-Omniguide-Origin), so on localhost the raw
        // location names no storefront and every keystroke 403s. Every other
        // caller already reads the override the host sets via init({currentPage}).
        origin: sanitizeUrl(getCurrentPage()) || undefined,
        signal: controller.signal,
      });

      // Out-of-order guard: a newer keystroke already rendered — drop this.
      if (myId <= lastRenderedIdRef.current) return;

      if (result.kind === 'aborted') {
        // A newer fire() owns loading state; don't flip it here.
        return;
      }

      lastRenderedIdRef.current = myId;
      setIsLoading(false);

      if (result.kind === 'disabled') {
        setIsDisabled(true);
        clearResults();
        return;
      }

      if (result.kind === 'error') {
        // Collapse the dropdown for this keystroke; the next one may succeed.
        clearResults();
        return;
      }

      const data = result.data;
      setResolvedQuery(typeof data?.query === 'string' ? data.query : query);

      if (data?.is_question) {
        setIsQuestion(true);
        setSections(EMPTY_SECTIONS);
        setHasResolvedEmpty(false);
        return;
      }

      const normalized = normalizeSections(data);
      setIsQuestion(false);
      setSections(normalized);
      setHasResolvedEmpty(isAllEmpty(normalized));
    },
    [apiBaseUrl, websiteCode],
  );

  const setQuery = useCallback(
    (rawQuery: string) => {
      if (isDisabled) return;
      clearTimer();

      const trimmed = rawQuery.trim();
      if (trimmed.length < TYPEAHEAD_MIN_QUERY_LENGTH) {
        // Below threshold: cancel in-flight + clear so stale results don't flash.
        abortRef.current?.abort();
        abortRef.current = null;
        clearResults();
        setIsLoading(false);
        return;
      }

      debounceTimerRef.current = setTimeout(() => {
        debounceTimerRef.current = null;
        void fire(trimmed);
      }, TYPEAHEAD_DEBOUNCE_MS);
    },
    [fire, isDisabled],
  );

  // Cancel pending timer / fetch on unmount.
  useEffect(() => {
    return () => {
      clearTimer();
      abortRef.current?.abort();
    };
  }, []);

  return {
    sections,
    resolvedQuery,
    isLoading,
    isDisabled,
    isQuestion,
    hasResolvedEmpty,
    setQuery,
    reset,
  };
}
