import React, { useState, useEffect, useMemo } from 'react';
import { DiscoveryOptionButton } from './DiscoveryOptionButton.js';

export interface AnswerChoice {
    /** AttributeValue id, e.g. "attrvalue_276447". */
    id: string;
    value: string;
    /**
     * How many products carry this value, when the backend supplies it. The
     * pin lane emits it; the CFQ lane does not, so it is optional and must be
     * read through `choicePopularity()` rather than directly. Both transports
     * normalize the wire's `product_count` to this name before it gets here.
     */
    productCount?: number | null;
}

export type AutocompleteRenderHint = 'autocomplete' | 'searchable_dropdown';

export interface DiscoveryAutocompleteProps {
    questionId: string;
    choices: AnswerChoice[];
    onSelectChoice: (choice: AnswerChoice) => void;
    selectedValue?: string | null;
    /**
     * Number of quick-pick pills shown above the option list (autocomplete
     * variant only). Ranked by `productCount` when the counts discriminate,
     * otherwise the first N in the order the backend sent.
     */
    topCount?: number;
    /**
     * How many options the list shows before the rest is one click away
     * (autocomplete variant only — the dropdown renders every match and
     * scrolls). Not a ceiling on what is reachable: the remainder is revealed
     * by "Show all N options", and the answer already chosen is never hidden
     * by the window.
     */
    maxResults?: number;
    placeholder?: string;
    /**
     * Accessible name for the filter input (autocomplete variant). Not
     * rendered visibly — there is no visible label in the comp.
     */
    filterLabel?: string;
    /**
     * Accessible name for the interactive control — should be the question
     * text so the choice list/combobox is announced with the question rather
     * than a generic group label.
     */
    ariaLabel?: string;
    /**
     * Render variant (SOI-616):
     *  - `'autocomplete'` (default): quick-pick pills over a browsable list of
     *    the remaining choices, with a filter box between them. Typing narrows
     *    the list across *every* choice; clearing restores it. Suited to long
     *    lists (50-200 values) where common picks should be one click away but
     *    nothing should need a keystroke to be found.
     *  - `'searchable_dropdown'`: listbox below a filter input, open on arrival
     *    (collapsed only when restoring a previous answer, which seeds the
     *    input and would otherwise show that one option), with keyboard
     *    navigation. Suited to ≤30 values.
     */
    renderHint?: AutocompleteRenderHint;
}

/** Every choice whose value contains `query`, in the order the backend sent. */
function filterChoices(choices: AnswerChoice[], query: string): AnswerChoice[] {
    const trimmed = query.trim().toLowerCase();
    if (!trimmed) return choices;
    return choices.filter((choice) => choice.value.toLowerCase().includes(trimmed));
}

/** The popularity signal, or null when this choice carries none. */
function choicePopularity(choice: AnswerChoice): number | null {
    const count = choice.productCount;
    return typeof count === 'number' && Number.isFinite(count) ? count : null;
}

/**
 * Whether the counts actually order the choices. Presence is not enough: one
 * count in two hundred, or the same count on every choice, ranks nothing — and
 * labelling that row "Popular" would be a claim about array position, which is
 * the thing this component is not allowed to do.
 */
function hasRankingSignal(choices: AnswerChoice[]): boolean {
    const seen = new Set<number>();
    for (const choice of choices) {
        const count = choicePopularity(choice);
        if (count !== null) seen.add(count);
        if (seen.size > 1) return true;
    }
    return false;
}

/**
 * Counted choices by descending count, then uncounted ones in server order.
 * Partitioned rather than sorted against a numeric sentinel, so a real count
 * of -1 is not mistaken for "no count" and a negative count still outranks a
 * choice that carries none.
 */
function rankByPopularity(choices: AnswerChoice[]): AnswerChoice[] {
    const counted = choices.filter((choice) => choicePopularity(choice) !== null);
    const uncounted = choices.filter((choice) => choicePopularity(choice) === null);
    counted.sort((a, b) => (choicePopularity(b) as number) - (choicePopularity(a) as number));
    return [...counted, ...uncounted];
}

/**
 * The first `max` matches — except that the answer already chosen is never
 * left off. A shopper whose pick sits at position 40 would otherwise see no
 * selected state anywhere on screen and no sign their answer registered.
 */
function windowWithSelected(
    matches: AnswerChoice[],
    max: number,
    selectedValue: string | null,
): AnswerChoice[] {
    const head = matches.slice(0, max);
    if (!selectedValue || head.some((choice) => choice.value === selectedValue)) return head;
    const chosen = matches.find((choice) => choice.value === selectedValue);
    if (!chosen) return head;
    return [...head.slice(0, Math.max(0, max - 1)), chosen];
}

// ── Icons (inline SVG, mirror the comp) ──────────────────────────────

function SearchIcon(): JSX.Element {
    return (
        <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth={1.6} aria-hidden="true">
            <circle cx="7" cy="7" r="4.6" />
            <path d="M11 11l3.6 3.6" strokeLinecap="round" />
        </svg>
    );
}

function ClearIcon(): JSX.Element {
    return (
        <svg viewBox="0 0 14 14" fill="none" stroke="currentColor" strokeWidth={1.8} strokeLinecap="round" aria-hidden="true">
            <path d="M3 3l8 8M11 3l-8 8" />
        </svg>
    );
}

function CheckIcon(): JSX.Element {
    return (
        <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
            <path d="M3.5 8.5l3 3 6-7" />
        </svg>
    );
}

// ── Variant: quick-pick chips + browsable option list (default) ──────
// Matches the PLP "combobox" comp (PLP Variant 1 v2): a quick-pick row sits
// above a pill search field (magnifier icon + live "N of M" count), with a
// multi-column grid of options beneath. The grid is present from the start —
// a shopper who does not know how a value is spelled has to be able to browse
// to it (SOI-2069) — and typing narrows it in place.

interface ChoiceFilter {
    query: string;
    onQueryChange: (next: string) => void;
    isFiltering: boolean;
    /** Every match, not just the ones inside the render window. */
    matchCount: number;
    shown: AnswerChoice[];
    canExpand: boolean;
    expanded: boolean;
    onToggleExpanded: () => void;
}

/**
 * Owns the filter query and the render window, and is the single place that
 * decides when either resets — the two used to be reset from two different
 * sites, which is how a lifted window survived into a question it was never
 * opened for.
 */
function useChoiceFilter(
    questionId: string,
    choices: AnswerChoice[],
    quickPicks: AnswerChoice[],
    maxResults: number,
    selectedValue: string | null,
): ChoiceFilter {
    const [query, setQuery] = useState('');
    const [expanded, setExpanded] = useState(false);

    // Keyed on the choice set as well as the id: adaptive mode re-serves the
    // same question id with a narrowed choice list, and a stale query there
    // shows "no options match" over a list that does have options.
    useEffect(() => {
        setQuery('');
        setExpanded(false);
    }, [questionId, choices]);

    const isFiltering = query.trim().length > 0;

    // Quick picks are already one click away above the list, so the unfiltered
    // list holds what they do not. Without this the first rows are a verbatim
    // copy of the chip row — guaranteed whenever the backend order already
    // correlates with popularity, which `facet_sort_mode: count_desc` makes
    // the common case. A filter still searches every choice.
    const pool = useMemo(() => {
        if (isFiltering || quickPicks.length === 0) return choices;
        const picked = new Set(quickPicks.map((choice) => choice.id));
        return choices.filter((choice) => !picked.has(choice.id));
    }, [choices, quickPicks, isFiltering]);

    const matches = useMemo(() => filterChoices(pool, query), [pool, query]);
    const shown = useMemo(
        () => (expanded ? matches : windowWithSelected(matches, maxResults, selectedValue)),
        [matches, expanded, maxResults, selectedValue],
    );

    return {
        query,
        onQueryChange: (next: string) => {
            setQuery(next);
            setExpanded(false);
        },
        isFiltering,
        matchCount: matches.length,
        shown,
        canExpand: matches.length > shown.length || expanded,
        expanded,
        onToggleExpanded: () => setExpanded((value) => !value),
    };
}

interface QuickPickRowProps {
    picks: AnswerChoice[];
    labelled: boolean;
    selectedValue: string | null;
    ariaLabel: string;
    onSelectChoice: (choice: AnswerChoice) => void;
}

/** `role="group"`, not `radiogroup`: `DiscoveryOptionButton` renders buttons
 *  with `aria-pressed`, and a radio group reporting zero radios is worse than
 *  no grouping at all. */
function QuickPickRow({
    picks,
    labelled,
    selectedValue,
    ariaLabel,
    onSelectChoice,
}: QuickPickRowProps): JSX.Element {
    return (
        <div className="omniguide-pr-cfq__popular">
            {labelled && <span className="omniguide-pr-cfq__popular-label">Popular</span>}
            <div
                className="omniguide-pr-questionnaire__choices omniguide-pr-cfq__choices"
                role="group"
                aria-label={ariaLabel}
            >
                {picks.map((choice) => (
                    <DiscoveryOptionButton
                        key={choice.id}
                        answer={{ id: choice.id, text: choice.value }}
                        isSelected={selectedValue === choice.value}
                        onSelect={() => onSelectChoice(choice)}
                    />
                ))}
            </div>
        </div>
    );
}

interface OptionGridProps {
    id: string;
    options: AnswerChoice[];
    selectedValue: string | null;
    ariaLabel: string;
    onSelectChoice: (choice: AnswerChoice) => void;
}

function OptionGrid({
    id,
    options,
    selectedValue,
    ariaLabel,
    onSelectChoice,
}: OptionGridProps): JSX.Element {
    return (
        <div id={id} className="omniguide-pr-cfq__grid" role="group" aria-label={ariaLabel}>
            {options.map((choice) => {
                const current = selectedValue === choice.value;
                return (
                    <button
                        key={choice.id}
                        type="button"
                        className={
                            current
                                ? 'omniguide-pr-cfq__opt omniguide-pr-cfq__opt--current'
                                : 'omniguide-pr-cfq__opt'
                        }
                        aria-pressed={current}
                        onClick={() => onSelectChoice(choice)}
                    >
                        <span className="omniguide-pr-cfq__opt-name">{choice.value}</span>
                        {current && (
                            <span className="omniguide-pr-cfq__opt-check" aria-hidden="true">
                                <CheckIcon />
                            </span>
                        )}
                    </button>
                );
            })}
        </div>
    );
}

interface FilterFieldProps {
    inputId: string;
    resultsId: string;
    query: string;
    placeholder: string;
    label: string;
    /** Always rendered, even when empty: a live region inserted together with
     *  its text is not announced, so the first keystroke would be silent. */
    status: string;
    onQueryChange: (next: string) => void;
}

/** Not a combobox: the options below are part of the question rather than a
 *  popup this input expands, so `role="combobox"` and a permanent
 *  `aria-expanded="true"` would both be lies. */
function FilterField({
    inputId,
    resultsId,
    query,
    placeholder,
    label,
    status,
    onQueryChange,
}: FilterFieldProps): JSX.Element {
    return (
        <div className="omniguide-pr-cfq__bar">
            <div className="omniguide-pr-cfq__field">
                <span className="omniguide-pr-cfq__field-icon" aria-hidden="true">
                    <SearchIcon />
                </span>
                <input
                    id={inputId}
                    type="text"
                    className="omniguide-pr-cfq__filter-input"
                    value={query}
                    onChange={(e) => onQueryChange(e.target.value)}
                    placeholder={placeholder}
                    autoComplete="off"
                    aria-controls={resultsId}
                    aria-label={label}
                />
                {query.length > 0 && (
                    <button
                        type="button"
                        className="omniguide-pr-cfq__clear"
                        aria-label="Clear search"
                        onClick={() => onQueryChange('')}
                    >
                        <ClearIcon />
                    </button>
                )}
            </div>
            <span className="omniguide-pr-cfq__meta" aria-live="polite">
                {status && <span className="omniguide-pr-cfq__count">{status}</span>}
            </span>
        </div>
    );
}

interface InlineFilterPillsProps {
    questionId: string;
    choices: AnswerChoice[];
    onSelectChoice: (choice: AnswerChoice) => void;
    selectedValue: string | null;
    topCount: number;
    maxResults: number;
    placeholder?: string;
    filterLabel: string;
    ariaLabel?: string;
}

function InlineFilterPills({
    questionId,
    choices,
    onSelectChoice,
    selectedValue,
    topCount,
    maxResults,
    placeholder,
    filterLabel,
    ariaLabel,
}: InlineFilterPillsProps): JSX.Element {
    const inputId = `omniguide-cfq-filter-${questionId}`;
    const resultsId = `${inputId}-results`;

    // The search field and the list only earn their place when there are more
    // options than the quick-pick chips already show — otherwise every choice
    // is one click away and typing to "filter it down" does nothing.
    const hasHiddenChoices = choices.length > topCount;
    const ranked = useMemo(() => hasRankingSignal(choices), [choices]);

    // Only re-order when there is something below to preserve the backend's
    // ordering in. When the chips *are* the whole list, re-ranking them would
    // silently discard the order the merchant chose via `facet_sort_mode`.
    const quickPicks = useMemo(
        () =>
            (ranked && hasHiddenChoices ? rankByPopularity(choices) : choices).slice(0, topCount),
        [choices, ranked, hasHiddenChoices, topCount],
    );

    const filter = useChoiceFilter(questionId, choices, quickPicks, maxResults, selectedValue);

    return (
        <div className="omniguide-pr-cfq">
            <QuickPickRow
                picks={quickPicks}
                labelled={hasHiddenChoices && ranked}
                selectedValue={selectedValue}
                ariaLabel={ariaLabel ? `${ariaLabel} — quick picks` : 'Quick picks'}
                onSelectChoice={onSelectChoice}
            />

            {hasHiddenChoices && (
                <>
                    <FilterField
                        inputId={inputId}
                        resultsId={resultsId}
                        query={filter.query}
                        placeholder={placeholder ?? `Search ${choices.length} options…`}
                        label={filterLabel}
                        status={filterStatus(filter, choices.length)}
                        onQueryChange={filter.onQueryChange}
                    />

                    {filter.matchCount > 0 ? (
                        <>
                            <OptionGrid
                                id={resultsId}
                                options={filter.shown}
                                selectedValue={selectedValue}
                                ariaLabel={gridLabel(ariaLabel, filter.isFiltering)}
                                onSelectChoice={onSelectChoice}
                            />
                            {filter.canExpand && (
                                <button
                                    type="button"
                                    className="omniguide-pr-cfq__more"
                                    onClick={filter.onToggleExpanded}
                                >
                                    {filter.expanded
                                        ? 'Show fewer options'
                                        : `Show all ${filter.matchCount} options`}
                                </button>
                            )}
                        </>
                    ) : (
                        // Carries the id the filter input points at, so
                        // `aria-controls` resolves in the empty state too.
                        <div id={resultsId} className="omniguide-pr-cfq__empty" role="status">
                            No options match “{filter.query.trim()}”
                        </div>
                    )}
                </>
            )}
        </div>
    );
}

/** What the live region says: the true match total while filtering, and the
 *  outcome of expanding, which is otherwise announced by nothing. */
function filterStatus(filter: ChoiceFilter, total: number): string {
    if (filter.isFiltering) return `${filter.matchCount} of ${total}`;
    return filter.expanded ? `Showing all ${filter.matchCount} options` : '';
}

function gridLabel(ariaLabel: string | undefined, isFiltering: boolean): string {
    if (isFiltering) return ariaLabel ? `${ariaLabel} — filtered options` : 'Filtered options';
    return ariaLabel ? `${ariaLabel} — more options` : 'More options';
}

// ── Variant: always-open searchable dropdown ─────────────────────────

interface SearchableDropdownProps {
    questionId: string;
    choices: AnswerChoice[];
    onSelectChoice: (choice: AnswerChoice) => void;
    selectedValue: string | null;
    placeholder: string;
    ariaLabel?: string;
}

function SearchableDropdown({
    questionId,
    choices,
    onSelectChoice,
    selectedValue,
    placeholder,
    ariaLabel,
}: SearchableDropdownProps): JSX.Element {
    // Only a value that is actually in the list counts as restored. Seeding the
    // input with a value the choices no longer contain leaves dead text over an
    // empty list, with nothing to clear it.
    const restored = useMemo(
        () =>
            selectedValue && choices.some((choice) => choice.value === selectedValue)
                ? selectedValue
                : '',
        [choices, selectedValue],
    );
    const [query, setQuery] = useState(restored);
    // Open on arrival so the choices can be browsed without a keystroke; a
    // restored answer is the one case where an open list would show only the
    // value already chosen.
    const [isOpen, setIsOpen] = useState(!restored);
    const [highlightedIndex, setHighlightedIndex] = useState(0);
    const listboxId = `omniguide-autocomplete-listbox-${questionId}`;

    // Keyed on `choices` as well, for the same reason the autocomplete variant
    // is: adaptive mode re-serves the same question id with a narrowed choice
    // list, and `restored` only changes if the chosen value changed — so a
    // stale query survived here and showed "No matches" over a list that did
    // have options. The fix for that landed on the other variant and was never
    // carried across.
    useEffect(() => {
        setQuery(restored);
        setIsOpen(!restored);
        setHighlightedIndex(0);
    }, [questionId, restored, choices]);

    // Uncapped: this variant's listbox scrolls, so a window here would put a
    // value out of reach for anyone who cannot spell it — the dead end the
    // autocomplete variant exists to avoid.
    const results = useMemo(() => filterChoices(choices, query), [choices, query]);

    // Clamp the highlight when the results shrink. Keyed off results.length
    // only — reading highlightedIndex via the functional updater avoids
    // re-subscribing (and the update-loop risk) on every move.
    useEffect(() => {
        setHighlightedIndex((i) => (i >= results.length ? 0 : i));
    }, [results.length]);

    const showList = isOpen && results.length > 0;

    const handleSelect = (choice: AnswerChoice) => {
        setQuery(choice.value);
        setIsOpen(false);
        onSelectChoice(choice);
    };

    const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
        if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
            e.preventDefault();
            // Either arrow reopens a dismissed list; only then does it move.
            if (!isOpen) {
                setIsOpen(true);
                return;
            }
            const step = e.key === 'ArrowDown' ? 1 : -1;
            setHighlightedIndex((i) => Math.min(Math.max(i + step, 0), results.length - 1));
        } else if (e.key === 'Enter') {
            e.preventDefault();
            // Guarded on the list being open: Escape then Enter used to select
            // a highlighted option the shopper could no longer see.
            if (!showList) return;
            const choice = results[highlightedIndex];
            if (choice) handleSelect(choice);
        } else if (e.key === 'Escape') {
            setIsOpen(false);
        }
    };

    return (
        <div className="omniguide-pr-autocomplete omniguide-pr-autocomplete--searchable-dropdown">
            <input
                type="text"
                className="omniguide-pr-autocomplete__input"
                value={query}
                onChange={(e) => {
                    setQuery(e.target.value);
                    setIsOpen(true);
                    setHighlightedIndex(0);
                }}
                onFocus={() => setIsOpen(true)}
                onKeyDown={handleKeyDown}
                placeholder={placeholder}
                role="combobox"
                aria-label={ariaLabel}
                aria-expanded={showList}
                aria-controls={listboxId}
                aria-autocomplete="list"
                aria-activedescendant={
                    showList && results[highlightedIndex]
                        ? `${listboxId}-option-${results[highlightedIndex].id}`
                        : undefined
                }
            />
            {showList && (
                <ul id={listboxId} role="listbox" className="omniguide-pr-autocomplete__list">
                    {results.map((choice, index) => (
                        <li
                            key={choice.id}
                            id={`${listboxId}-option-${choice.id}`}
                            role="option"
                            aria-selected={index === highlightedIndex}
                            className={
                                index === highlightedIndex
                                    ? 'omniguide-pr-autocomplete__option omniguide-pr-autocomplete__option--highlighted'
                                    : 'omniguide-pr-autocomplete__option'
                            }
                            onMouseDown={(e) => e.preventDefault()}
                            onClick={() => handleSelect(choice)}
                            onMouseEnter={() => setHighlightedIndex(index)}
                        >
                            {choice.value}
                        </li>
                    ))}
                </ul>
            )}
            {isOpen && query.trim() && results.length === 0 && (
                <div id={listboxId} className="omniguide-pr-autocomplete__no-results" role="status">
                    No matches
                </div>
            )}
        </div>
    );
}

export function DiscoveryAutocomplete({
    questionId,
    choices,
    onSelectChoice,
    selectedValue = null,
    topCount = 5,
    maxResults = 12,
    placeholder,
    filterLabel = 'Or filter it down here',
    ariaLabel,
    renderHint = 'autocomplete',
}: DiscoveryAutocompleteProps): JSX.Element {
    if (renderHint === 'searchable_dropdown') {
        return (
            <SearchableDropdown
                questionId={questionId}
                choices={choices}
                onSelectChoice={onSelectChoice}
                selectedValue={selectedValue}
                placeholder={placeholder ?? 'Filter options…'}
                ariaLabel={ariaLabel}
            />
        );
    }

    return (
        <InlineFilterPills
            questionId={questionId}
            choices={choices}
            onSelectChoice={onSelectChoice}
            selectedValue={selectedValue}
            topCount={topCount}
            maxResults={maxResults}
            placeholder={placeholder}
            filterLabel={filterLabel}
            ariaLabel={ariaLabel}
        />
    );
}
