import React, { useEffect, useMemo, useState } from 'react';
import { SearchCategoryChip, SearchQueryRow, detectQuestion } from './SearchSuggestionChips.js';
import { SearchTypeaheadSections } from './SearchTypeaheadSections.js';
import { useCountdown } from '../../hooks/useCountdown.js';
import { useTypeaheadSearch } from '../../hooks/useTypeaheadSearch.js';
import { safeNavigate, buildSafeUrl } from '../../utils/navigation.js';
import type {
    TypeaheadAnyHit,
    TypeaheadSectionKey,
    TypeaheadSectionPayload,
    TypeaheadSections,
} from '@swiftotter/omniguide-core';

const CHAT_PROMPT_TEXT = 'Ask a question.';
const TYPEAHEAD_ID_PREFIX = 'omniguide-ta';

export interface SearchEmptyStateProps {
    onExampleClick: (example: string) => void;
    isMobile?: boolean;
    variant?: 'search' | 'category';
    suggestedQuestions?: string[];
    seedQuestions?: string[];
    welcomeText?: string;
    hideTitle?: boolean;
    defaultSearchExamples?: string[];
    disabled?: boolean;
    connectionStatus?: string;
    reconnectInfo?: { attempt: number; maxAttempts: number; delayMs: number } | null;
    /** Live (in-progress) search text — drives the instant ask-hero. */
    liveQuery?: string;
    /** Opt into the federated typeahead surface (SOI-708). Search variant only. */
    typeahead?: boolean;
    /**
     * Store base URL used to resolve a typeahead hit's (often relative) `url`
     * into an absolute one before navigating. Required when the SDK runs in an
     * iframe whose origin isn't the store (e.g. the chrome extension), where a
     * relative URL would resolve against — and be rejected as — a non-http
     * origin, silently blocking the click.
     */
    aiSearchStoreUrl?: string;
    /**
     * Called when a typeahead hit is activated (click / Enter). Default
     * navigates to the hit's url. Provide to intercept (e.g. SPA routing).
     */
    onSelectHit?: (hit: TypeaheadAnyHit, sectionKey: TypeaheadSectionKey) => void;
    /**
     * Navigate to the storefront's own search results for the typed query.
     * Optional because the shared panel cannot know that URL — it is per
     * platform (`/search.php?search_query=` on BigCommerce) — so the host
     * supplies it. Without it the bottom bar still states the match count,
     * just without the link.
     */
    onSeeAllResults?: (query: string) => void;
    /** What to call the assistant on the ask button, from `ui.assistantLabel`. */
    assistantLabel?: string;
    /**
     * Rendered at the foot of the instant panel, above the bottom bar, and
     * only while nothing has been typed — the same condition that gates
     * "Common searches" (SOI-2289).
     *
     * A node rather than an import: the thing we put here is a carousel, and
     * `@swiftotter/omniguide-carousel` already depends on this package. The
     * caller that owns both edges passes it in — see `packages/bigcommerce`.
     */
    emptyStateFooter?: React.ReactNode;
}

const DEFAULT_CATEGORY_EXAMPLES = ['What are the best options?', 'Compare products', 'Help me choose'];

export const SearchEmptyState: React.FC<SearchEmptyStateProps> = ({
    onExampleClick,
    isMobile,
    variant = 'search',
    suggestedQuestions = [],
    seedQuestions = [],
    welcomeText = '',
    hideTitle = false,
    defaultSearchExamples,
    disabled = false,
    connectionStatus,
    reconnectInfo,
    liveQuery = '',
    typeahead = false,
    aiSearchStoreUrl,
    onSelectHit,
    onSeeAllResults,
    assistantLabel,
    emptyStateFooter,
}) => {
    const isConnectionDisabled = connectionStatus === 'connecting' || connectionStatus === 'reconnecting' || connectionStatus === 'disconnected';
    const countdown = useCountdown(reconnectInfo, connectionStatus === 'reconnecting');
    const isCategory = variant === 'category';
    // Federated typeahead (SOI-708) — only the search variant feeds it. The hook
    // is always called (Rules of Hooks); it stays inert until fed a query.
    const ta = useTypeaheadSearch();
    // Pull the stable setQuery out: depending on the whole `ta` object (a fresh
    // object every render) in the effect below would loop — setState → re-render
    // → new `ta` → effect → setQuery → fetch → setState → … forever.
    const taSetQuery = ta.setQuery;
    const typeaheadActive = typeahead && !isCategory && !ta.isDisabled;
    const [activeHitId, setActiveHitId] = useState<string | null>(null);
    useEffect(() => {
        if (!typeaheadActive) return;
        taSetQuery(liveQuery);
        // Reset keyboard focus when the query changes.
        setActiveHitId(null);
    }, [typeaheadActive, liveQuery, taSetQuery]);

    // Resolve to an absolute store URL. The hit's `url` is usually a relative
    // path; left relative, safeNavigate resolves it against
    // window.location.origin — which in the chrome-extension iframe is a
    // chrome-extension:// origin that fails the http(s) check, silently
    // blocking the click. Prefer the configured store base, then the document
    // base (the extension sets <base href> to the store URL), then the page
    // origin. buildSafeUrl rejects javascript:/data:/vbscript: and validates
    // the result, so a hit URL can't become DOM XSS — which matters twice over
    // now that this value is also rendered into an `href`.
    const resolveHitHref = (hit: TypeaheadAnyHit): string | undefined => {
        if (!('url' in hit) || !hit.url) return undefined;
        const base = aiSearchStoreUrl
            || (typeof document !== 'undefined' ? document.baseURI : undefined);
        // No `?? hit.url` fallback here, unlike the click path below: a null
        // means buildSafeUrl refused the URL, and an href is written into the
        // DOM where the browser will follow it without asking safeNavigate.
        return buildSafeUrl(base, hit.url) ?? undefined;
    };

    // A row exists to be navigated to, so a hit with no usable URL is not a
    // result — it is a pointer cursor and a hover state over nothing.
    //
    // This is not hypothetical and not a backend bug: `url` is optional on
    // every hit type. Measured on staging, "power kicker" returns three brand
    // hits and all three have `url: null`, so the whole Brands section was
    // three dead rows. Dropping them here rather than rendering a control that
    // cannot work also removes the section entirely when nothing survives,
    // because SearchTypeaheadSections renders nothing for an empty section.
    //
    // `found` is deliberately left alone. It is the backend's total match
    // count, not a count of this page, so adjusting it by what one page's
    // filter removed would invent a number. Only products.found is read (by
    // the bottom bar), and product hits carry URLs.
    const linkableSections = useMemo<TypeaheadSections>(() => {
        // Generic and per-section rather than a loop over the key union: the
        // four payloads have different hit types, and an indexed write makes
        // TypeScript demand the intersection of all four.
        const keep = <H,>(section: TypeaheadSectionPayload<H>): TypeaheadSectionPayload<H> => ({
            found: section.found,
            hits: section.hits.filter(
                (hit) => resolveHitHref(hit as TypeaheadAnyHit) !== undefined,
            ),
        });
        return {
            products: keep(ta.sections.products),
            categories: keep(ta.sections.categories),
            content: keep(ta.sections.content),
            brands: keep(ta.sections.brands),
        };
        // resolveHitHref is recreated every render but reads only
        // aiSearchStoreUrl, so that is the real dependency.
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [ta.sections, aiSearchStoreUrl]);

    const handleSelectHit = (hit: TypeaheadAnyHit, sectionKey: TypeaheadSectionKey) => {
        if (onSelectHit) {
            onSelectHit(hit, sectionKey);
            return;
        }
        if ('url' in hit && hit.url) {
            const base = aiSearchStoreUrl
                || (typeof document !== 'undefined' ? document.baseURI : undefined);
            const target = buildSafeUrl(base, hit.url) ?? hit.url;
            safeNavigate(target);
        }
    };
    const examples = isCategory
        ? (suggestedQuestions.length > 0 ? suggestedQuestions.slice(0, 3) : DEFAULT_CATEGORY_EXAMPLES)
        : (seedQuestions.length > 0 ? seedQuestions.slice(0, 6) : (defaultSearchExamples || DEFAULT_CATEGORY_EXAMPLES));

    const connectionNotice = isConnectionDisabled && (
        <p className="omniguide-chat__connection-notice">
            {connectionStatus === 'disconnected'
                ? 'Unable to connect to the assistant.'
                : connectionStatus === 'reconnecting' && reconnectInfo && reconnectInfo.attempt >= 2
                    ? countdown !== null && countdown > 0
                        ? `Next try in ${countdown}s (${reconnectInfo.attempt}/${reconnectInfo.maxAttempts})`
                        : `Reconnecting... (${reconnectInfo.attempt}/${reconnectInfo.maxAttempts})`
                    : <>Connecting<span className="omniguide-chat__connecting-dots"><span>.</span><span>.</span><span>.</span></span></>}
        </p>
    );

    // Search instant panel: live typeahead sections + a bottom bar (SOI-2263).
    // The Enter-key ask-hero that used to head this panel is gone: Enter no
    // longer submits, so a row whose whole call to action was "Press Enter"
    // would be a dead control. Asking is now an explicit button, here and in
    // the search bar above.
    if (!isCategory) {
        const trimmedQuery = liveQuery.trim();
        // The query the count belongs to, which is NOT what is in the field. A
        // keystroke updates `liveQuery` immediately; `found` only changes when the
        // debounced request resolves. Linking "See all 41 results" to the live text
        // sends the shopper to a search for something nothing has counted yet.
        const countedQuery = ta.resolvedQuery.trim() || trimmedQuery;
        const typed = trimmedQuery.length > 0;
        // Backend question-detection is authoritative when typeahead is live;
        // otherwise fall back to the local heuristic.
        const isQuestion = typeaheadActive ? ta.isQuestion : detectQuestion(liveQuery);
        // Counted over the LINKABLE hits, not the raw ones: a response whose
        // every hit lacks a URL has nothing to show, and reading it as "has
        // hits" would render an empty panel instead of "No matches".
        const taHasHits =
            typeaheadActive &&
            (linkableSections.products.hits.length > 0 ||
                linkableSections.categories.hits.length > 0 ||
                linkableSections.content.hits.length > 0 ||
                linkableSections.brands.hits.length > 0);
        // "Nothing to show", not "the backend found nothing" — those stopped
        // being the same thing once url-less hits are dropped. A response of
        // three brand hits with no URLs leaves `hasResolvedEmpty` false while
        // there is nothing left to render, and reading the old flag would show
        // a panel with neither results nor an explanation.
        //
        // `resolvedQuery` is the query the current sections belong to, so it is
        // non-empty exactly once a response has been rendered. That also keeps
        // the hint from flashing mid-request: while a new query is in flight the
        // previous response is still on screen, so taHasHits is still true.
        const taResolved = typeaheadActive && ta.resolvedQuery.trim().length > 0;
        const taNoMatches = taResolved && typed && !isQuestion && !taHasHits;
        const showCommonSearches = !typed;
        // `found` is the total match count, not the page size — the whole reason
        // the payload carries it separately from `hits`. `hits.length` here would
        // read "See all 8 results" on a query with hundreds.
        //
        // PRODUCTS only, deliberately. "See all N results" navigates to the
        // storefront's product search, so adding categories, brands and editorial
        // matches would promise a number that page cannot show. One number, one
        // destination, and they agree.
        const totalFound = taHasHits ? ta.sections.products.found : 0;
        // From `ui.assistantLabel` (e.g. "Ask Roger") — config, never a literal:
        // a tenant's persona must not reach a shared component. It does NOT
        // fall back to the panel title, which tenants set to a store name.
        const askLabel = assistantLabel?.trim() || 'Ask the assistant';
        const canAsk = typed && !disabled;

        return (
            <div className={`omniguide-chat__empty-state omniguide-instant ${isMobile ? 'omniguide-chat__empty-state--mobile' : ''}`}>
                {connectionNotice}
                {taHasHits && (
                    <SearchTypeaheadSections
                        sections={linkableSections}
                        idPrefix={TYPEAHEAD_ID_PREFIX}
                        activeId={activeHitId}
                        onSelect={handleSelectHit}
                        onHover={setActiveHitId}
                        hrefFor={resolveHitHref}
                    />
                )}
                {taNoMatches && (
                    <p className="omniguide-instant__typed-hint">
                        No matches for &ldquo;{trimmedQuery}&rdquo;.
                    </p>
                )}
                {showCommonSearches && (
                    <div className="omniguide-instant__section">
                        <h4 className="omniguide-instant__heading">Common searches</h4>
                        <div
                            className={`omniguide-instant__rows ${disabled ? 'omniguide-chips--disabled' : ''}`}
                            role="group"
                            aria-label="Example questions to get started"
                            aria-disabled={disabled || undefined}
                        >
                            {examples.map((example) => (
                                <SearchQueryRow
                                    key={example}
                                    text={example}
                                    onClick={disabled ? () => {} : () => onExampleClick(example)}
                                />
                            ))}
                        </div>
                    </div>
                )}
                {/* Foot of the empty state, under the same "nothing typed"
                    gate as "Common searches" (SOI-2289). Placed above the
                    bottom bar for the same reason the hint strip it replaced
                    was below it — though in practice the two never co-occur,
                    since the bar needs hits or a question and this needs an
                    empty field. */}
                {showCommonSearches && emptyStateFooter}
                {/* Bottom bar. Both controls preventDefault on mousedown only to
                    keep focus in the search field — the panel is closed by a
                    document-level mousedown (SearchUI) that ignores anything
                    inside the modal, so these clicks were never at risk. Acting
                    on onClick rather than onMouseDown is what keeps them
                    keyboard-activatable, unlike the result rows. */}
                {(totalFound > 0 || canAsk) && (
                <div className="omniguide-ta-bar">
                    <span className="omniguide-ta-bar__slot">
                        {totalFound > 0 && (
                            onSeeAllResults ? (
                                <button
                                    type="button"
                                    className="omniguide-ta-bar__all"
                                    onMouseDown={(e) => e.preventDefault()}
                                    onClick={() => onSeeAllResults(countedQuery)}
                                >
                                    See all {totalFound} result{totalFound === 1 ? '' : 's'}
                                    <svg viewBox="0 0 16 16" width="13" height="13" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d="M3 8h9M8.5 4l4 4-4 4" /></svg>
                                </button>
                            ) : (
                                <span className="omniguide-ta-bar__all-static">
                                    {totalFound} result{totalFound === 1 ? '' : 's'}
                                </span>
                            )
                        )}
                    </span>
                    {canAsk && (
                        <button
                            type="button"
                            className="omniguide-ta-bar__ask"
                            // Explicit, because the visible lead-in is hidden below a
                            // 440px container — without this the button's accessible
                            // name would change with the panel's width.
                            aria-label={`${askLabel} about ${trimmedQuery}`}
                            onMouseDown={(e) => e.preventDefault()}
                            onClick={() => onExampleClick(trimmedQuery)}
                        >
                            <span className="omniguide-ta-bar__ask-lead">Not sure which one?</span>
                            <span className="omniguide-ta-bar__ask-cta">
                                {askLabel}
                                <svg width="11" height="11" viewBox="0 0 12 12" aria-hidden="true"><path d="M2.5 1.2 10 6l-7.5 4.8Z" fill="currentColor" /></svg>
                            </span>
                        </button>
                    )}
                </div>
                )}
            </div>
        );
    }

    return (
        <div className={`omniguide-chat__empty-state ${isMobile ? 'omniguide-chat__empty-state--mobile' : ''}`}>
            {!hideTitle && (
                <h3 className="omniguide-chat__empty-state-title">
                    {CHAT_PROMPT_TEXT}
                </h3>
            )}
            <>
                {welcomeText && (
                    <div className="omniguide-qa__answer" style={{ marginBottom: '16px' }}>
                        {welcomeText}
                    </div>
                )}
                {connectionNotice}
                <div
                    className={`omniguide-chips ${disabled ? 'omniguide-chips--disabled' : ''}`}
                    role="group"
                    aria-label="Example questions to get started"
                    aria-disabled={disabled || undefined}
                >
                    {examples.map((example) => (
                        <SearchCategoryChip
                            key={example}
                            text={example}
                            onClick={disabled ? () => {} : () => onExampleClick(example)}
                            isSelected={false}
                        />
                    ))}
                </div>
            </>
        </div>
    );
};
