import React, { useState } from 'react';
import { SearchCheckIcon, SearchMagnifierIcon, SearchSparkIcon, SearchArrowIcon } from './SearchIcons.js';

export interface SearchChipProps {
    text: string;
    onClick: () => void;
    isSelected?: boolean;
}

const QUESTION_WORDS = ['what', 'which', 'how', 'why', 'can', 'does', 'do', 'is', 'are', 'should', 'when', 'where', 'who', 'will', 'whats', "what's"];
const ADVISORY_RE = /\b(best|vs|versus|difference|compare|recommend|help me|better|ideal|suitable|which|good for)\b/;

/**
 * Heuristic: does this example read as a question to ask the assistant
 * (vs. a plain keyword lookup)? Mirrors the design's ogDetectQuestion.
 */
export function detectQuestion(raw: string): boolean {
    const s = (raw || '').trim().toLowerCase();
    if (!s) return false;
    if (s.endsWith('?')) return true;
    const words = s.split(/\s+/);
    if (QUESTION_WORDS.includes(words[0] ?? '')) return true;
    if (ADVISORY_RE.test(s)) return true;
    return words.length >= 6;
}

/**
 * Instant-panel "common searches" row: leading icon (spark for questions,
 * magnifier for lookups), the example text, an "Ask" tag for questions,
 * and a trailing arrow on hover.
 */
export const SearchQueryRow: React.FC<SearchChipProps> = ({ text, onClick }) => {
    const isQuestion = detectQuestion(text);

    const handleKeyDown = (e: React.KeyboardEvent) => {
        if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            onClick();
        }
    };

    return (
        <button
            type="button"
            onClick={onClick}
            onKeyDown={handleKeyDown}
            className={`omniguide-query-row ${isQuestion ? 'omniguide-query-row--question' : ''}`}
            aria-label={isQuestion ? `Ask: ${text}` : `Search: ${text}`}
        >
            <span className="omniguide-query-row__icon" aria-hidden="true">
                {isQuestion ? <SearchSparkIcon /> : <SearchMagnifierIcon />}
            </span>
            <span className="omniguide-query-row__text">{text}</span>
            {isQuestion && <span className="omniguide-query-row__tag">Ask</span>}
            <span className="omniguide-query-row__arrow" aria-hidden="true"><SearchArrowIcon /></span>
        </button>
    );
};

export const SearchGradientChip: React.FC<SearchChipProps> = ({ text, onClick, isSelected = false }) => {
    const [isHovered, setIsHovered] = useState(false);
    const [isFocused, setIsFocused] = useState(false);

    const handleKeyDown = (e: React.KeyboardEvent) => {
        if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            onClick();
        }
    };

    return (
        <button
            onClick={onClick}
            onKeyDown={handleKeyDown}
            onMouseEnter={() => setIsHovered(true)}
            onMouseLeave={() => setIsHovered(false)}
            onFocus={() => setIsFocused(true)}
            onBlur={() => setIsFocused(false)}
            className="omniguide-chip--gradient"
            data-hovered={isHovered}
            data-selected={isSelected}
            data-focused={isFocused}
            aria-label={`Ask: ${text}`}
            aria-pressed={isSelected}
        >
            <span className={`omniguide-chip__inner ${isSelected ? 'omniguide-chip__inner--selected' : ''}`}>
                {isSelected && <SearchCheckIcon />}
                {text}
            </span>
        </button>
    );
};

