import React, { useState, useRef, useEffect } from 'react';
import { SearchPrivacySettings } from './SearchPrivacySettings.js';
import type { SearchPrivacySettingsProps } from './SearchPrivacySettings.js';
import { useCountdown } from '../../hooks/useCountdown.js';
import { SearchMagnifierIcon } from './SearchIcons.js';

const MAX_INPUT_LENGTH = 200;
const MAX_INPUT_ERROR_MSG = `Maximum ${MAX_INPUT_LENGTH} characters allowed`;

export interface SearchChatInputProps {
    onSendMessage: (content: string) => void;
    isLoading?: boolean;
    isMobile?: boolean;
    isCategory?: boolean;
    isCollapsed?: boolean;
    onCollapseToggle?: () => void;
    onResetChat?: () => void;
    autoFocusAfterSend?: boolean;
    variant?: 'search' | 'category';
    privacySettingsProps?: Omit<SearchPrivacySettingsProps, 'isMobile' | 'onResetChat'>;
    connectionStatus?: string;
    reconnectInfo?: { attempt: number; maxAttempts: number; delayMs: number } | null;
    /** Render as the instant-panel top search bar (leading magnifier, slim field, no submit button). */
    topSearch?: boolean;
    /**
     * Opens the assistant with the typed query — the only live control in the
     * top search bar (SOI-2263). The arrow beside the field and the Enter key
     * are deliberately inert there: keyword search is a separate ticket, and
     * shipping them as no-ops beats shipping them wired to the wrong target.
     */
    onAskAssistant?: (query: string) => void;
    /**
     * Label for that button, e.g. "Ask Roger". Comes from the host's
     * `ui.assistantLabel` config — never hardcoded, so no tenant's assistant
     * name lands in a shared component. Falls back to a generic label rather
     * than dropping the button: a host that has not named its assistant still
     * needs the only live control in the bar.
     */
    assistantLabel?: string;
    /** Fires on every keystroke with the current field value (for the live instant panel). */
    onValueChange?: (value: string) => void;
    /** Placeholder for the mobile ask pill, e.g. "Ask a question about binoculars…" (SOI-757). */
    placeholder?: string;
    /**
     * Start the category ask box expanded (text field shown) instead of the
     * "or, ask a question" pill. Used when an outer control (e.g. the guide
     * teaser) already serves as the entry point, so the in-card input shouldn't
     * repeat it. Category variant only.
     */
    askInitiallyExpanded?: boolean;
    /** Submit button label (desktop). Defaults to "Send"; the guide ask uses "Go". */
    submitLabel?: string;
}

export const SearchChatInput: React.FC<SearchChatInputProps> = ({
    onSendMessage,
    isLoading = false,
    isMobile = false,
    isCategory = false,
    isCollapsed = false,
    onCollapseToggle,
    onResetChat,
    autoFocusAfterSend = false,
    privacySettingsProps,
    connectionStatus,
    reconnectInfo,
    topSearch = false,
    onAskAssistant,
    assistantLabel,
    onValueChange,
    placeholder,
    askInitiallyExpanded = false,
    submitLabel = 'Send',
}) => {
    const [input, setInput] = useState('');
    const [isInputFocused, setIsInputFocused] = useState(false);
    const [showInputLimitError, setShowInputLimitError] = useState(false);
    // Category ask box (SOI-757): collapsed to an "or, ask a question" pill that
    // expands into the text field on demand — unless an outer entry point already
    // triggered it (askInitiallyExpanded), in which case the field shows directly.
    const [askExpanded, setAskExpanded] = useState(askInitiallyExpanded);
    const inputRef = useRef<HTMLInputElement>(null);
    const prevIsLoadingRef = useRef(isLoading);

    const isConnectionDisabled = connectionStatus === 'connecting' || connectionStatus === 'reconnecting' || connectionStatus === 'disconnected';
    const isDisabled = isLoading || isConnectionDisabled;
    const countdown = useCountdown(reconnectInfo, connectionStatus === 'reconnecting');

    const getPlaceholder = () => {
        if (topSearch) return 'Search or ask anything…';
        if (isMobile) return placeholder ?? 'Ask a question';
        if (isCategory) return placeholder ?? 'Ask anything…';
        return 'Ask Anything';
    };

    useEffect(() => {
        if (prevIsLoadingRef.current && !isLoading && inputRef.current && autoFocusAfterSend) {
            inputRef.current.focus({ preventScroll: true });
        }
        prevIsLoadingRef.current = isLoading;
    }, [isLoading, autoFocusAfterSend]);

    // Focus the search field once when it mounts (panel opened), on every
    // surface. `autoFocus` alone isn't reliable enough to skip this: it lost
    // the race against the mobile bottom sheet's animation, and (SOI-2170)
    // against third-party host-page embeds (e.g. a marketing popup iframe)
    // that grab focus right after mount on desktop too — confirmed live,
    // where the shopper had to click the search box a second time to get a
    // cursor. Focus explicitly after layout settles. Search only (not the
    // category flow).
    useEffect(() => {
        if (isCategory) return;
        const id = window.setTimeout(() => inputRef.current?.focus({ preventScroll: true }), 30);
        return () => window.clearTimeout(id);
    }, [isCategory]);

    // Focus the field as soon as the ask box expands from its button state.
    useEffect(() => {
        if (askExpanded) {
            inputRef.current?.focus({ preventScroll: true });
        }
    }, [askExpanded]);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        // SOI-2263: Enter does nothing in the typeahead bar. Submitting used to
        // open the assistant, which made the key ambiguous once an explicit
        // "ask" button existed beside it. What Enter should do instead is the
        // next ticket's call, so it stays inert rather than guessing.
        if (topSearch) return;
        const trimmedInput = input.trim();
        if (trimmedInput && !isDisabled) {
            const messageToSend = trimmedInput;
            setInput('');
            onValueChange?.('');
            setShowInputLimitError(false);
            if (inputRef.current) {
                inputRef.current.value = '';
            }
            onSendMessage(messageToSend);
        }
    };

    const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const value = e.target.value;
        setInput(value);
        onValueChange?.(value);
        setShowInputLimitError(value.length >= MAX_INPUT_LENGTH);
    };

    const handleInputPaste = (e: React.ClipboardEvent<HTMLInputElement>) => {
        const pastedText = e.clipboardData?.getData('text') || '';
        const currentValue = input;
        const target = e.target as HTMLInputElement;
        const selectionStart = target.selectionStart || 0;
        const selectionEnd = target.selectionEnd || 0;
        const resultingLength = currentValue.length - (selectionEnd - selectionStart) + pastedText.length;
        if (resultingLength > MAX_INPUT_LENGTH) {
            setShowInputLimitError(true);
        }
    };

    const handleFocus = () => {
        setIsInputFocused(true);
        if (isCollapsed && onCollapseToggle) {
            onCollapseToggle();
        }
    };

    const inputId = isMobile ? 'chat-input-mobile' : 'chat-input';
    const errorId = isMobile ? 'chat-input-error-mobile' : 'chat-input-error';

    if (isMobile) {
        return (
            <div className="omniguide-chat__mobile-input">
                <form
                    onSubmit={handleSubmit}
                    className="omniguide-chat__mobile-input-form"
                    role="search"
                    aria-label="Ask a question"
                >
                    <label htmlFor={inputId} className="sr-only">Type your question</label>
                    <input
                        id={inputId}
                        ref={inputRef}
                        type="text"
                        value={input}
                        onChange={handleInputChange}
                        onPaste={handleInputPaste}
                        placeholder={getPlaceholder()}
                        disabled={isDisabled}
                        maxLength={MAX_INPUT_LENGTH}
                        className="omniguide-chat__mobile-input-field"
                        aria-describedby={showInputLimitError ? errorId : undefined}
                        aria-invalid={showInputLimitError}
                    />
                    <button
                        type="submit"
                        disabled={!input.trim() || isDisabled}
                        className="omniguide-chat__mobile-submit-btn"
                        data-disabled={!input.trim() || isDisabled}
                        aria-label={isLoading ? 'Sending message...' : 'Send message'}
                    >
                        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
                            <path d="M5 12H19M19 12L12 5M19 12L12 19" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" />
                        </svg>
                    </button>
                </form>
                {showInputLimitError && (
                    <p id={errorId} className="omniguide-chat__input-error" role="alert" aria-live="assertive">
                        {MAX_INPUT_ERROR_MSG}
                    </p>
                )}
            </div>
        );
    }

    return (
        <div className={`omniguide-chat__input-container ${topSearch ? 'omniguide-chat__input-container--top' : ''} ${isCategory ? 'omniguide-chat__input-container--category' : ''} ${isCollapsed ? 'omniguide-chat__input-container--collapsed' : ''}`}>
            {isCategory && !askExpanded ? (
                <button
                    type="button"
                    className="omniguide-chat__ask-toggle"
                    onClick={() => setAskExpanded(true)}
                >
                    or, ask a question
                </button>
            ) : (
            <form
                onSubmit={handleSubmit}
                className={`omniguide-chat__input-form ${topSearch ? 'omniguide-chat__input-form--top' : ''} ${isCategory ? 'omniguide-chat__input-form--category' : ''}`}
                data-focused={isInputFocused}
                role="search"
                aria-label="Ask a question"
            >
                {topSearch && (
                    <span className="omniguide-chat__input-leading-icon" aria-hidden="true">
                        <SearchMagnifierIcon />
                    </span>
                )}
                {isCategory && (
                    <span className="omniguide-chat__input-search-icon" aria-hidden="true">
                        <svg width="20" height="20" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                            <circle cx="11" cy="11" r="7" stroke="currentColor" strokeWidth="2" />
                            <path d="m20 20-3.5-3.5" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
                        </svg>
                    </span>
                )}
                <label htmlFor={inputId} className="sr-only">Type your question</label>
                <input
                    id={inputId}
                    ref={inputRef}
                    type="text"
                    value={input}
                    onChange={handleInputChange}
                    onPaste={handleInputPaste}
                    placeholder={getPlaceholder()}
                    disabled={isDisabled}
                    maxLength={MAX_INPUT_LENGTH}
                    autoFocus={topSearch}
                    className={`omniguide-chat__input ${isCategory ? 'omniguide-chat__input--category' : ''}`}
                    aria-describedby={showInputLimitError ? errorId : undefined}
                    aria-invalid={showInputLimitError}
                    onFocus={handleFocus}
                    onBlur={(e) => {
                        // Don't reset focus state if user clicked an interactive element
                        if (e.relatedTarget?.matches?.('a, button, input, select, textarea')) {
                            return;
                        }
                        setIsInputFocused(false);
                    }}
                />
                {topSearch && (
                    // Decorative, and marked as such (SOI-2263). The design puts an
                    // arrow here, but keyword search is a separate ticket, so this
                    // control does nothing. A focusable button announced "Search"
                    // that then does nothing is worse than no control at all — the
                    // shopper cannot tell it from a broken one, and a screen-reader
                    // user is told an action exists that does not. So it leaves the
                    // a11y tree and the tab order entirely, and the CSS drops its
                    // pointer affordances. Give it behaviour in the follow-up ticket
                    // and this reverts to a real button.
                    <span className="omniguide-chat__go-btn" aria-hidden="true">
                        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" aria-hidden="true">
                            <path d="M5 12H19M19 12L12 5M19 12L12 19" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" />
                        </svg>
                    </span>
                )}
                {topSearch && onAskAssistant && (
                    <>
                        <span className="omniguide-chat__or" aria-hidden="true">or</span>
                        <button
                            type="button"
                            className="omniguide-chat__ask-btn"
                            // Not disabled on an empty field. This is the only live
                            // control in the bar, and the assistant opens perfectly
                            // well with nothing typed — that is its own blank state,
                            // not an error. Dimming it on open made the one thing
                            // that works look like the one thing that is broken.
                            disabled={isDisabled}
                            onClick={() => onAskAssistant(input.trim())}
                        >
                            <svg width="13" height="13" viewBox="0 0 12 12" aria-hidden="true">
                                <path d="M2.5 1.2 10 6l-7.5 4.8Z" fill="currentColor" />
                            </svg>
                            <span className="omniguide-chat__ask-btn-label">{assistantLabel?.trim() || 'Ask the assistant'}</span>
                        </button>
                    </>
                )}
                {!topSearch && (
                    <button
                        type="submit"
                        disabled={!input.trim() || isDisabled}
                        className={`omniguide-chat__submit-btn ${isCategory ? 'omniguide-chat__submit-btn--category' : ''}`}
                        data-disabled={!input.trim() || isDisabled}
                        data-focused={isInputFocused}
                        aria-label={isLoading ? 'Sending message...' : 'Send message'}
                    >
                        <span className="omniguide-chat__submit-label">{submitLabel}</span>
                        <svg xmlns="http://www.w3.org/2000/svg" width="19" height="19" viewBox="0 0 19 19" fill="none" aria-hidden="true" focusable="false">
                            <path d="M14.2002 7.90792L7.9422 1.64991L9.5921 0L18.6667 9.07459L9.5921 18.149L7.9422 16.4991L14.2002 10.2413H0V7.90792H14.2002Z" fill="currentColor"/>
                        </svg>
                    </button>
                )}
            </form>
            )}
            {showInputLimitError && (
                <p id={errorId} className="omniguide-chat__input-error" role="alert" aria-live="assertive">
                    {MAX_INPUT_ERROR_MSG}
                </p>
            )}
            {!topSearch && (privacySettingsProps || (isCategory && isConnectionDisabled)) && (
                <div className="omniguide-chat__input-footer">
                    {privacySettingsProps ? (
                        <SearchPrivacySettings
                            {...privacySettingsProps}
                            isMobile={false}
                            onResetChat={onResetChat}
                        />
                    ) : <div />}
                    {isCategory && isConnectionDisabled && (
                        <span className="omniguide-chat__input-status">
                            {connectionStatus === 'disconnected'
                                ? 'Unable to connect'
                                : connectionStatus === 'reconnecting' && reconnectInfo && reconnectInfo.attempt >= 2
                                    ? countdown !== null && countdown > 0
                                        ? `Next try in ${countdown}s (${reconnectInfo.attempt}/${reconnectInfo.maxAttempts})`
                                        : <>Reconnecting<span className="omniguide-chat__connecting-dots"><span>.</span><span>.</span><span>.</span></span> ({reconnectInfo.attempt}/{reconnectInfo.maxAttempts})</>
                                    : <>Connecting<span className="omniguide-chat__connecting-dots"><span>.</span><span>.</span><span>.</span></span></>}
                        </span>
                    )}
                </div>
            )}
        </div>
    );
};
